const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
$u='https://forum.thegradcafe.com/search/?q=personal%20statement%20editing'
curl.exe -s -L -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 30 --compressed $u -o "$env:TEMP\\gc.html"
$c = Get-Content "$env:TEMP\\gc.html" -Raw
Write-Output ("LEN=" + $c.Length)
$txt = $c -replace '(?s)<script.*?</script>',' ' -replace '(?s)<style.*?</style>',' ' -replace '<[^>]+>',' ' -replace '\\s+',' '
Write-Output $txt.Substring(0,[Math]::Min(2500,$txt.Length))`;
const r = await tools.pwsh({ description: "Inspect GradCafe search page text", command: cmd, timeoutMs: 90000 });
console.log(r.kind === 'foreground' ? r.stdout.text : JSON.stringify(r));
